engine=create_async_engine(settings.database_url, future=True); Session=async_sessionmaker(engine, expire_on_commit=False)
async def init_db():
    async with engine.begin() as conn: await conn.run_sync(Base.metadata.create_all)
async def get_conversation(s: AsyncSession, cid: str): return await s.get(ConversationModel,cid)
async def get_transcript(s: AsyncSession, cid: str): return (await s.execute(select(TranscriptModel).where(TranscriptModel.conversation_id==cid))).scalar_one_or_none()
async def get_result(s: AsyncSession, cid: str, mode: ProcessingMode): return (await s.execute(select(ProcessingResultModel).where(ProcessingResultModel.conversation_id==cid,ProcessingResultModel.mode==mode))).scalar_one_or_none()
